            for v in row:
                if v==c: run+=1
                else: best=max(best,run); run=0
            best=max(best,run)
        for col in range(w):
            run=0
            for v in g[row][col] if False else (g[r][col] for r in range(h)):
                pass
            run=0
            for r in range(h):
                if g[r][col]==c: run+=1
                else: best=max(best,run); run=0
            best=max(best,run)
        return best
