        seen=set(); 
        for (r0,c0) in sorted(cells):
            if (r0,c0) in seen: continue
            run=[(r0,c0)]; seen.add((r0,c0))
            c1=c0+1
            while (r0,c1) in cs and c1<w:
                run.append((r0,c1)); seen.add((r0,c1)); c1+=1
            if len(run)>=2: res.append(('h',run))
        for (r0,c0) in sorted(cells):
            if (r0,c0) in seen: continue
            run=[(r0,c0)]; seen.add((r0,c0))
            r1=r0+1
            while (r1,c0) in cs and r1<h:
                run.append((r1,c0)); seen.add((r1,c0)); r1+=1
            if len(run)>=2: res.append(('v',run))
