            rng=range(r0+1,tr) if tr>r0 else range(tr+1,r0)
            # row selector
            mr={i for i,_ in pos.get(next(iter(mkcols)),[])} if mkcols else set()
            rows=mr&set(range(h)) if sel=='markrows' else (set(range(min(rng),max(rng)+1)) if rng else set())
            if sel in ('minus_first','minus_last'):
                rows=sorted(rows)[1:] if sel=='minus_first' else sorted(rows)[::-1]
